/**
 * main.js — self-contained Three.js small-intestine scene.
 *
 * No backend. Assets consumed (all generated by tools/, all with provenance):
 *   assets/small_intestine.glb              real CT-segmentation surfaces
 *   assets/si_centreline.json               duodenal + jejuno-ileal centreline
 *   assets/small_intestine_vessels.json     three trees + arcade anastomoses
 *   assets/si_flow.json                     flow paths with real v = Q/A
 *   assets/small_intestine_model.json       haemodynamics, motility, ACAT
 *   assets/small_intestine_expression.json  measured single-cell ADME profile
 *                                           (absent if the pull failed - the
 *                                            page then says so explicitly)
 *
 * Public API (also used by the automated probe):
 *   const api = await createIntestineScene({ container, assetBase, view })
 *   api.setView('organ'|'vessels'|'wall'|'villus')
 *   api.setPlaybackRate(x), api.setParticleDensity(f), api.setStation(i)
 *   api.setTree(name, on), api.dispose()
 *   window.__si3d  diagnostics for the headless benchmark
 */

import * as THREE from 'three';
import { GLTFLoader } from '../vendor/jsm/loaders/GLTFLoader.js';
import { OrbitControls } from '../vendor/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from '../vendor/jsm/environments/RoomEnvironment.js';

import { buildVesselMesh, TREE_COLOR } from './vessels.js';
import { FlowSystem } from './flow.js';
import { buildLumen, applyPeristalsis, WAVE } from './peristalsis.js';
import { buildWallSegment, buildVillusUnit, buildBrushBorder, MAG } from './villus.js';
import { HUD, NARROW_PX } from './hud.js';

const WALL_OFFSET = new THREE.Vector3(0, -2600, 0);
const VILLUS_OFFSET = new THREE.Vector3(0, -5200, 0);
const BRUSH_OFFSET = new THREE.Vector3(76, -5168, 8);
const STATION_CN = ['十二指肠', '空肠', '回肠'];

const CONTEXT = {
  colon: { color: 0x7a6a52, opacity: 0.20, cn: '结肠' },
  stomach: { color: 0x9b7a62, opacity: 0.18, cn: '胃' },
  liver: { color: 0x8a4a3a, opacity: 0.22, cn: '肝脏（门静脉衔接）' },
  pancreas: { color: 0xa89470, opacity: 0.20, cn: '胰腺' },
  duodenum: { color: 0xd49a82, opacity: 0.55, cn: '十二指肠（轮廓锚定）' },
  small_bowel: { color: 0xd98a7a, opacity: 0.13, cn: '小肠占位包络（实测分割）' }
};

async function getJSON (u) {
  const r = await fetch(u);
  if (!r.ok) return null;
  return r.json();
}

export async function createIntestineScene (opts = {}) {
  const container = opts.container || document.body;
  const base = opts.assetBase || './assets/';
  const stage = (s) => { window.__si3dStage = s; };

  stage('renderer:begin');
  const renderer = new THREE.WebGLRenderer({
    antialias: true, powerPreference: 'high-performance', alpha: false
  });
  const narrow0 = container.clientWidth < NARROW_PX;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, narrow0 ? 1.6 : 2));
  renderer.setSize(container.clientWidth, container.clientHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.04;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  container.appendChild(renderer.domElement);
  stage('renderer:ok');

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x070a10);
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.environmentIntensity = 0.62;
  stage('pmrem:ok');

  const camera = new THREE.PerspectiveCamera(
    40, container.clientWidth / container.clientHeight, 1, 20000);
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true; controls.dampingFactor = 0.07;
  controls.minDistance = 30; controls.maxDistance = 9000;

  const key = new THREE.DirectionalLight(0xfff1e8, 2.25); key.position.set(1, 1, 0.95);
  const fill = new THREE.DirectionalLight(0x9fc4ff, 0.58); fill.position.set(-1.1, 0.3, -0.5);
  const rim = new THREE.DirectionalLight(0xffd8c0, 0.5); rim.position.set(0.1, -0.8, -1);
  scene.add(key, fill, rim, new THREE.AmbientLight(0xffffff, 0.16));

  // ------------------------------------------------------------- assets
  stage('fetch:begin');
  const [cl, ves, flowSpec, model, expr, geoRep, vesRep, flowRep] = await Promise.all([
    getJSON(base + 'si_centreline.json'),
    getJSON(base + 'small_intestine_vessels.json'),
    getJSON(base + 'si_flow.json'),
    getJSON(base + 'small_intestine_model.json'),
    getJSON(base + 'small_intestine_expression.json'),
    getJSON(base + 'geometry_report.json'),
    getJSON(base + 'vessel_report.json'),
    getJSON(base + 'flow_report.json')
  ]);
  stage('fetch:ok');

  const glb = await new GLTFLoader().loadAsync(base + 'small_intestine.glb');
  // trimesh writes a GLB whose default-scene index can be absent, in which case
  // GLTFLoader leaves .scene undefined and only populates .scenes
  const glbRoot = glb.scene || (glb.scenes && glb.scenes[0]);
  if (!glbRoot) throw new Error('small_intestine.glb parsed with no scene node');
  stage('glb:ok');

  // ------------------------------------------------------------- organ view
  const root = new THREE.Group(); scene.add(root);
  const organ = new THREE.Group(); organ.name = 'organ'; root.add(organ);
  const surfaces = {};
  let faceTotal = 0;
  // collect first, re-parent after: adding a mesh to `organ` detaches it from
  // its glTF parent, and mutating children DURING traverse() skips/undefines
  // entries in the array three.js is iterating
  const glbMeshes = [];
  glbRoot.traverse((o) => { if (o.isMesh) glbMeshes.push(o); });
  glbMeshes.forEach((o) => {
    const nm = Object.keys(CONTEXT).find((k) => o.name.indexOf(k) >= 0) || o.name;
    const spec = CONTEXT[nm] || { color: 0x888888, opacity: 0.3, cn: nm };
    o.material = new THREE.MeshStandardMaterial({
      color: spec.color, roughness: 0.58, metalness: 0.02,
      transparent: spec.opacity < 0.99, opacity: spec.opacity,
      depthWrite: spec.opacity > 0.5, side: THREE.DoubleSide
    });
    o.userData.cn = spec.cn;
    surfaces[nm] = o;
    const g = o.geometry;
    faceTotal += (g.index ? g.index.count : g.attributes.position.count) / 3;
    organ.add(o);
  });

  const lumen = buildLumen(cl, { stride: 2 });
  const lumenMat = applyPeristalsis(new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 0.46, metalness: 0.02, side: THREE.DoubleSide
  }), lumen.arcLength_mm);
  const lumenMesh = new THREE.Mesh(lumen.geometry, lumenMat);
  lumenMesh.name = 'lumen'; organ.add(lumenMesh);

  // centre the whole abdomen on its own bounding box
  const bb = new THREE.Box3().setFromObject(organ);
  const ctr = bb.getCenter(new THREE.Vector3());
  const rad = bb.getBoundingSphere(new THREE.Sphere()).radius;
  organ.position.sub(ctr);

  // ------------------------------------------------------------- vessels view
  const vesselsG = new THREE.Group(); vesselsG.name = 'vessels'; root.add(vesselsG);
  vesselsG.position.sub(ctr);
  const treeMeshes = {}; const treeStats = {};
  for (const [name, tree] of Object.entries(ves.trees)) {
    const built = buildVesselMesh({ ...tree, name }, { rScale: 1.0 });
    const mat = new THREE.MeshStandardMaterial({
      color: built.color, roughness: 0.34, metalness: 0.05
    });
    const m = new THREE.Mesh(built.geometry, mat); m.name = 'tree_' + name;
    treeMeshes[name] = m; treeStats[name] = built.stats; vesselsG.add(m);
  }
  // arcade anastomoses and vasa recta: declared non-flow-carrying, drawn as lines
  const mkLines = (edges, color, w) => {
    const pts = [];
    for (const e of edges) { pts.push(...e[0], ...e[1]); }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
    return new THREE.LineSegments(g, new THREE.LineBasicMaterial({
      color, transparent: true, opacity: w
    }));
  };
  const arcadeL = mkLines(ves.anastomoses.arcade_edges_scene_mm, 0xe0564e, 0.78);
  arcadeL.name = 'arcades'; vesselsG.add(arcadeL);
  const vrL = mkLines(ves.anastomoses.vasa_recta_edges_scene_mm, 0xf08a70, 0.9);
  vrL.name = 'vasa_recta'; vesselsG.add(vrL);
  const rootL = mkLines(ves.root_of_mesentery_scene_mm.slice(0, -1)
    .map((p, i) => [p, ves.root_of_mesentery_scene_mm[i + 1]]), 0x7fc8a0, 0.5);
  rootL.name = 'root_of_mesentery'; vesselsG.add(rootL);

  const flow = new FlowSystem(flowSpec, narrow0 ? 190 : 330);
  flow.points.name = 'flow'; vesselsG.add(flow.points);
  flow.setPixelRatio(renderer.getPixelRatio());
  if (flow.setParticleScale) flow.setParticleScale(1.9);

  // keep a translucent envelope + lumen in the vessel view for context
  const vesselCtx = new THREE.Group(); vesselCtx.name = 'vessel_context';
  vesselsG.add(vesselCtx);

  // ------------------------------------------------------------- wall view
  const wall = buildWallSegment(model, { mag: MAG.wall });
  wall.group.position.copy(WALL_OFFSET); root.add(wall.group);

  // ------------------------------------------------------------- villus view
  const vu = buildVillusUnit(model, { mag: MAG.villus });
  vu.group.position.copy(VILLUS_OFFSET); root.add(vu.group);
  const bb2 = buildBrushBorder(model, { mag: MAG.brush });
  bb2.group.position.copy(BRUSH_OFFSET); root.add(bb2.group);

  // ------------------------------------------------------------- HUD
  const hudCanvas = document.createElement('canvas');
  hudCanvas.style.cssText = 'position:absolute;inset:0;pointer-events:none;z-index:5';
  container.appendChild(hudCanvas);
  const hud = new HUD(hudCanvas);

  let view = opts.view || 'organ';
  let rate = 1.0, station = -1, tSec = 0;
  // Camera framing is computed from each view's own bounding sphere rather than
  // hard-coded distances, so no view can end up off-centre or clipped when the
  // geometry changes. The direction per view is fixed; the distance is not.
  const VIEW_DIR = {
    organ:   new THREE.Vector3(0.18, 0.30, 1.0).normalize(),
    vessels: new THREE.Vector3(0.42, 0.34, 1.0).normalize(),
    wall:    new THREE.Vector3(-1.0, 0.42, 0.92).normalize(),
    villus:  new THREE.Vector3(0.40, 0.14, 1.0).normalize()
  };
  const VIEW_GROUP = () => ({
    organ: [surfaces.small_bowel || organ, lumenMesh],
    // the particle Points object carries a synthetic bounding box, so the
    // vessel view is framed on the tree meshes and the arcade network only
    vessels: [treeMeshes.mesenteric_artery, treeMeshes.mesenteric_vein,
              treeMeshes.lymphatic, arcadeL, vrL],
    wall: [wall.group],
    villus: [vu.group, bb2.group]
  }[view]);

  const VIEW_MARGIN = { organ: 1.22, vessels: 1.18, wall: 1.12, villus: 1.04 };
  function frameView (margin) {
    margin = margin || VIEW_MARGIN[view] || 1.2;
    const box = new THREE.Box3();
    for (const o of VIEW_GROUP()) if (o) box.expandByObject(o);
    if (box.isEmpty()) return;
    const sph = box.getBoundingSphere(new THREE.Sphere());
    const fov = THREE.MathUtils.degToRad(camera.fov);
    const dist = (sph.radius * margin) / Math.sin(Math.min(fov, 2 * Math.atan(
      Math.tan(fov / 2) * camera.aspect)) / 2);
    camera.position.copy(sph.center).addScaledVector(VIEW_DIR[view], dist);
    camera.near = Math.max(0.5, dist - sph.radius * 3);
    camera.far = dist + sph.radius * 6;
    camera.updateProjectionMatrix();
    controls.target.copy(sph.center);
    controls.minDistance = sph.radius * 0.25;
    controls.maxDistance = dist * 4;
    controls.update();
  }

  function applyView () {
    organ.visible = (view === 'organ');
    vesselsG.visible = (view === 'vessels');
    wall.group.visible = (view === 'wall');
    vu.group.visible = (view === 'villus');
    bb2.group.visible = (view === 'villus');
    frameView();
  }
  applyView();

  function resize () {
    const w = container.clientWidth, h = container.clientHeight;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, w < NARROW_PX ? 1.6 : 2));
    renderer.setSize(w, h);
    camera.aspect = w / h; camera.updateProjectionMatrix();
    hud.resize(w, h, Math.min(window.devicePixelRatio, 2));
    flow.setPixelRatio(renderer.getPixelRatio());
  }
  resize();
  const ro = new ResizeObserver(resize); ro.observe(container);

  // pulsatile modulation of arterial particle speed from the heart model's own
  // aortic flow waveform; venous and lymphatic paths stay steady
  const waveArr = flowSpec.aortic_flow_waveform_normalised || [1];
  const HR_HZ = 64.45 / 60.0;

  const clock = new THREE.Clock();
  let raf = 0, disposed = false;
  const diag = { fps: 0, frames: 0, view, faces: faceTotal };

  function frame () {
    if (disposed) return;
    raf = requestAnimationFrame(frame);
    const dt = Math.min(clock.getDelta(), 0.05);
    tSec += dt * rate;
    const now = performance.now();

    if (lumenMat.userData.shader) {
      lumenMat.userData.shader.uniforms.uTime.value = tSec;
      lumenMat.userData.shader.uniforms.uStationHi.value = station;
    }
    if (view === 'vessels') {
      const ph = (tSec * HR_HZ) % 1.0;
      const amp = waveArr[Math.floor(ph * waveArr.length) % waveArr.length];
      flow.update(dt * 1000, rate * Math.max(0.12, amp));
    }
    if (view === 'villus') vu.animate(tSec, 1.0);

    controls.update();
    renderer.render(scene, camera);
    hud.tickFps(now);
    drawHud();
    diag.fps = hud.fps; diag.frames++; diag.view = view;
  }

  function drawHud () {
    const c = hud.ctx; if (!c) return;
    c.clearRect(0, 0, hud.w, hud.h);
    hud.boxes = [];
    if (!hud.visible) return;
    const narrow = hud.narrow;
    const pad = narrow ? 9 : 13;
    const fs = narrow ? 10.5 : 12;
    const lines = [];
    lines.push(['小肠 · ' + ({ organ: '器官与蠕动', vessels: '肠系膜血管与血流',
      wall: '肠壁四层剖面', villus: '绒毛–隐窝单元' }[view]), '#e9eef6', fs + 2]);
    if (view === 'organ') {
      lines.push([`中心线 ${geoRep.centreline.total_length_m} m（活体参考 3–5 m）`, '#93a3ba', fs]);
      lines.push([`蠕动波 ${WAVE.speed_mm_s / 10} cm/s · 分节 ${WAVE.f_duodenum_per_min}→${WAVE.f_ileum_per_min} 次/分`, '#93a3ba', fs]);
      if (!narrow) lines.push([`环形皱襞 ×3 · 绒毛 ×10 · 微绒毛 ×20 = ×${model.micro.amplification_total}`, '#93a3ba', fs]);
      lines.push([`管腔为参数化（contour_anchored = false）`, '#d9b06a', fs]);
    } else if (view === 'vessels') {
      const a = flowRep.trees.mesenteric_artery, v = flowRep.trees.mesenteric_vein,
            l = flowRep.trees.lymphatic;
      lines.push([`SMA ${a.velocity_cm_s.trunk} cm/s · SMV ${v.velocity_cm_s.trunk} cm/s`, '#93a3ba', fs]);
      if (!narrow) lines.push([`淋巴 ${l.velocity_cm_s.trunk} cm/s（显示增益 ${l.display_gain}×）`, '#d9b06a', fs]);
      lines.push([`Murray 残差 0 · 树间最小间隙 ${vesRep.cross_tree_clearance.min_surface_gap_over_all_tree_pairs_mm} mm`, '#93a3ba', fs]);
      lines.push([`逆流采样点 ${flowRep.audit.retrograde_samples_total} / ${flowRep.audit.total_samples_audited}`, '#93a3ba', fs]);
    } else if (view === 'wall') {
      lines.push([`放大 ×${wall.stats.magnification}（真实比例均匀放大）`, '#93a3ba', fs]);
      lines.push([`壁厚 ${wall.stats.wall_thickness_mm} mm · 皱襞 ${wall.stats.plicae.count} 道`, '#93a3ba', fs]);
      if (!narrow) lines.push([`绒毛 ${wall.stats.villi.height_mm} mm（已发表 0.5–1.6 mm）`, '#93a3ba', fs]);
      lines.push([`层厚取已发表范围，非本受试者实测`, '#d9b06a', fs]);
    } else {
      lines.push([`放大 ×${vu.stats.magnification} · 刷状缘插图 ×${bb2.stats.magnification}`, '#93a3ba', fs]);
      lines.push([`绒毛 ${vu.stats.villus_height_mm} mm · 隐窝 ${vu.stats.crypt_depth_mm} mm · 肠上皮细胞 ${model.micro.enterocyte_height_um} µm`, '#93a3ba', fs]);
      if (!narrow) lines.push([`更新周期 ${vu.stats.turnover_days[0]}–${vu.stats.turnover_days[1]} 天（动画已声明）`, '#93a3ba', fs]);
    }
    lines.push([`${hud.fps.toFixed(0)} fps`, '#7fd0a8', fs]);

    const wmax = Math.min(hud.w - pad * 2, narrow ? hud.w - pad * 2 : 430);
    c.save();
    c.font = `${fs}px -apple-system,"PingFang SC",sans-serif`;
    let hTot = pad * 2;
    for (const [, , f] of lines) hTot += f + 5;
    c.fillStyle = 'rgba(8,12,20,0.72)';
    c.strokeStyle = 'rgba(120,140,170,0.26)';
    c.beginPath();
    // right-aligned on wide viewports (the DOM control panel owns the left),
    // bottom-left on narrow ones where the control panel moves to the bottom
    const bw = wmax, bh = hTot - pad;
    const bx = narrow ? pad : Math.max(pad, hud.w - pad - bw);
    const by = pad;
    let y = by + fs + 2;
    c.roundRect(bx, by, bw, bh, 9); c.fill(); c.stroke();
    hud.boxes.push({ name: 'hud_panel', x: bx, y: by, w: bw, h: bh });
    for (const [txt, col, f] of lines) {
      c.font = `${f}px -apple-system,"PingFang SC",sans-serif`;
      c.fillStyle = col;
      let t = txt;
      while (c.measureText(t).width > bw - 20 && t.length > 4) t = t.slice(0, -2);
      c.fillText(t, bx + 10, y + 4);
      hud.boxes.push({ name: 'line', x: bx + 10, y: y - f + 4,
                       w: Math.min(c.measureText(t).width, bw - 20), h: f + 2 });
      y += f + 5;
    }
    c.restore();
  }

  frame();
  stage('ready');

  const api = {
    setView (v) { if (VIEW_DIR[v]) { view = v; applyView(); } },
    frameView,
    getView () { return view; },
    setPlaybackRate (x) { rate = Math.max(0.05, Math.min(4, x)); },
    setParticleDensity (f) { flow.setDensity(f); },
    setStation (i) { station = i; },
    setTree (name, on) {
      if (treeMeshes[name]) treeMeshes[name].visible = on;
      flow.setTreeEnabled(name, on);
    },
    setArcades (on) { arcadeL.visible = on; vrL.visible = on; },
    setSurface (name, on) { if (surfaces[name]) surfaces[name].visible = on; },
    setHud (on) { hud.visible = on; },
    hudOverflow () {
      return hud.boxes.filter(b => b.x < -0.5 || b.y < -0.5 ||
        b.x + b.w > hud.w + 0.5 || b.y + b.h > hud.h + 0.5);
    },
    stats () {
      return {
        faces_in_glb: faceTotal,
        lumen: { rings: lumen.rings, triangles: lumen.triangles,
                 arc_length_mm: lumen.arcLength_mm, contour_anchored: false },
        trees: treeStats,
        arcade_edges: ves.anastomoses.arcade_edges_scene_mm.length,
        vasa_recta_edges: ves.anastomoses.vasa_recta_edges_scene_mm.length,
        flow: flow.diagnostics(),
        wall: wall.stats, villus: vu.stats, brush: bb2.stats,
        expression_present: !!expr,
        expression: expr ? { cell_types: expr.cell_types.length,
                             genes: expr.genes.length,
                             cells: expr.n_cells.reduce((a, b) => a + b, 0) } : null,
        magnifications: MAG,
        renderer: renderer.getContext().getParameter(
          renderer.getContext().getExtension('WEBGL_debug_renderer_info')
            ? renderer.getContext().getExtension('WEBGL_debug_renderer_info').UNMASKED_RENDERER_WEBGL
            : renderer.getContext().RENDERER) || 'unknown'
      };
    },
    diag, hud, renderer, camera, scene, controls, flow,
    parts: { surfaces, lumen: lumenMesh, trees: treeMeshes, arcades: arcadeL,
             vasaRecta: vrL, wall: wall.group, villus: vu.group, brush: bb2.group },
    lumenInfo: lumen, wallStats: wall.stats, villusStats: vu.stats,
    brushStats: bb2.stats, reports: { geo: geoRep, vessel: vesRep, flow: flowRep },
    model, expression: expr,
    dispose () {
      disposed = true; cancelAnimationFrame(raf); ro.disconnect();
      renderer.dispose(); pmrem.dispose(); container.innerHTML = '';
    }
  };
  window.__si3d = api;
  return api;
}
